import * as path from 'path';
import { BrowserContext, expect, Locator, Page } from '@playwright/test';

export const ADMIN_STATE = path.resolve(__dirname, '../../../auth/admin.json');
export const TEST_COMPANY_ID = '4432bd2f-3f47-43cf-8ef2-b0c16436f025';
export const TECHS = { sent: 'QA-F5 tech', skipped: 'QA-Tech Gamma' } as const;

export type Lang = 'en' | 'he';
export const L = {
  en: { textSelected: /Text selected/, send: /^Send$/, result: /Sent to 1 of 2/, resultSrc: 'Sent to ', skipped: /Skipped:.*QA-Tech Gamma/s },
  he: { textSelected: /הודעה לנבחרים/, send: /^שליחה$/, result: /נשלח ל-1 מתוך 2/, resultSrc: 'נשלח ל-', skipped: /QA-Tech Gamma/ },
} as const;

export type SmsGuard = { posts: number; fulfilled: number; blocked: number; bodies: unknown[] };

const CORS = {
  'access-control-allow-origin': '*',
  'access-control-allow-headers': '*',
  'access-control-allow-methods': 'POST, OPTIONS',
};

/** Перехват отправки. Вызывать ДО page.goto. */
export async function interceptSending(context: BrowserContext): Promise<SmsGuard> {
  const g: SmsGuard = { posts: 0, fulfilled: 0, blocked: 0, bodies: [] };
  context.on('request', (req) => {
    if (req.method() === 'POST' && /functions\/v1\/message-technicians/.test(req.url())) g.posts++;
  });
  await context.route(/functions\/v1\/message-technicians/, async (route) => {
    const req = route.request();
    if (req.method() === 'OPTIONS') return route.fulfill({ status: 204, headers: CORS, body: '' });
    let body: { technician_ids?: string[] } | null = null;
    try { body = req.postDataJSON(); } catch { /* ignore */ }
    g.bodies.push(body);
    const ids = body?.technician_ids ?? [];
    g.fulfilled++;
    await route.fulfill({
      status: 200,
      headers: { ...CORS, 'content-type': 'application/json' },
      body: JSON.stringify({
        results: [
          { technician_id: ids[0], technician_name: TECHS.sent, status: 'sent' },
          { technician_id: ids[1], technician_name: TECHS.skipped, status: 'skipped', reason: 'no_consent' },
        ],
      }),
    });
  });
  await context.route(/functions\/v1\/(send-sms|assignment-notices)/, async (route) => {
    g.blocked++;
    await route.abort();
  });
  return g;
}

/** Ничего не ушло в сеть: каждый POST перехвачен, их ровно столько, сколько Send; в каждом — 2 техника. */
export function expectNothingSent(g: SmsGuard, sends: number) {
  expect(g.fulfilled, 'перехвачено message-technicians == числу Send').toBe(sends);
  expect(g.posts, 'все POST message-technicians перехвачены (ни одного в сеть)').toBe(g.fulfilled);
  expect(g.blocked, 'send-sms / assignment-notices не вызывались').toBe(0);
  for (const b of g.bodies) {
    expect((b as { technician_ids?: string[] } | null)?.technician_ids ?? [], 'в запросе ровно 2 отмеченных QA-техника').toHaveLength(2);
  }
}

export async function openTechnicians(page: Page, lang: Lang) {
  await page.addInitScript(([l, c]) => {
    try {
      window.localStorage.setItem('preferred-language', l);
      window.localStorage.setItem('selected-company-id', c);
    } catch { /* ignore */ }
  }, [lang, TEST_COMPANY_ID] as const);
  await page.goto('/technicians');
  await expect(textSelectedButton(page, lang)).toBeVisible({ timeout: 25_000 });
  await expect(page.getByText(TECHS.skipped).first()).toBeVisible({ timeout: 25_000 });
}

export function textSelectedButton(page: Page, lang: Lang): Locator {
  return page.getByRole('button', { name: L[lang].textSelected }).first();
}

function techCheckbox(page: Page, name: string): Locator {
  return page.getByRole('row').filter({ hasText: name }).first().getByRole('checkbox').first();
}

/** Отметить ровно двух QA-техников; кнопка показывает (2). */
export async function selectQaTechs(page: Page, lang: Lang) {
  for (const t of [TECHS.sent, TECHS.skipped]) {
    const cb = techCheckbox(page, t);
    await cb.scrollIntoViewIfNeeded();
    if (!(await cb.isChecked())) await cb.click();
    await expect(cb).toBeChecked();
  }
  await expect(textSelectedButton(page, lang)).toHaveText(/\(2\)/);
}

/** Text selected → текст → Send. Кнопку нажимаем клавиатурой: на телефоне её может накрывать предыдущий тост. */
export async function sendText(page: Page, lang: Lang, msg: string) {
  await textSelectedButton(page, lang).press('Enter');
  const ta = page.locator('#technician-message');
  await expect(ta).toBeVisible();
  await ta.fill(msg);
  const send = page.getByRole('button', { name: L[lang].send });
  await expect(send).toBeEnabled();
  await send.click();
}

/**
 * Записывает положение карточек тоста результата в каждом кадре (requestAnimationFrame) с момента появления
 * в течение windowMs. Вызывать ДО Send. Карточка = самый внешний предок текста результата с непрозрачным фоном,
 * лежащий внутри position:fixed контейнера.
 */
export async function startToastSampler(page: Page, lang: Lang, windowMs = 1200) {
  await page.evaluate(([src, win]) => {
    const w = window as unknown as { __qaToast: { frames: { t: number; boxes: number[][] }[]; done: boolean } };
    w.__qaToast = { frames: [], done: false };
    const t0 = performance.now();
    let start: number | null = null;
    const loop = () => {
      const snap = document.evaluate(`//*[contains(text(), "${src}")]`, document.body, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
      const boxes: number[][] = [];
      for (let i = 0; i < snap.snapshotLength; i++) {
        let el = snap.snapshotItem(i) as HTMLElement | null;
        let card: HTMLElement | null = null;
        while (el && el !== document.body) {
          const cs = getComputedStyle(el);
          if (cs.position === 'fixed') break;
          if (cs.backgroundColor !== 'rgba(0, 0, 0, 0)' && cs.backgroundColor !== 'transparent') card = el;
          el = el.parentElement;
        }
        if (card && el && el !== document.body) {
          const r = card.getBoundingClientRect();
          if (r.width > 0) boxes.push([r.left, r.right]);
        }
      }
      if (boxes.length) {
        if (start === null) start = performance.now();
        w.__qaToast.frames.push({ t: performance.now() - start, boxes });
      }
      const elapsed = start === null ? performance.now() - t0 : performance.now() - start;
      if ((start === null && elapsed < 20_000) || (start !== null && elapsed < win)) requestAnimationFrame(loop);
      else w.__qaToast.done = true;
    };
    requestAnimationFrame(loop);
  }, [L[lang].resultSrc, windowMs] as const);
}

/** Ждёт конца записи и возвращает крайние координаты карточек за всё время появления. */
export async function sampledExtremes(page: Page) {
  await expect.poll(() => page.evaluate(() => (window as unknown as { __qaToast: { done: boolean } }).__qaToast.done), {
    message: 'запись кадров появления тоста закончилась', timeout: 25_000,
  }).toBe(true);
  return page.evaluate(() => {
    const f = (window as unknown as { __qaToast: { frames: { t: number; boxes: number[][] }[] } }).__qaToast.frames;
    const all = f.flatMap((x) => x.boxes);
    return { frames: f.length, minLeft: Math.min(...all), maxRight: Math.max(...all), innerWidth: window.innerWidth };
  });
}

export type ToastCard = {
  left: number; right: number; top: number; bottom: number; width: number;
  scrollWidth: number; clientWidth: number; bgAlpha: number; opacity: number; text: string; textRight: number;
};

/** Текущие карточки тостов результата (по тексту «Sent to …» / «נשלח ל-…»). */
export async function resultCards(page: Page, lang: Lang): Promise<{ innerWidth: number; cards: ToastCard[] }> {
  return page.evaluate((src) => {
    const snap = document.evaluate(`//*[contains(text(), "${src}")]`, document.body, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
    const cards: ToastCard[] = [];
    const alpha = (c: string) => { const m = c.match(/rgba?\(([^)]+)\)/); if (!m) return 1; const p = m[1].split(',').map((s) => s.trim()); return p.length === 4 ? Number(p[3]) : 1; };
    for (let i = 0; i < snap.snapshotLength; i++) {
      let el = snap.snapshotItem(i) as HTMLElement | null;
      let card: HTMLElement | null = null;
      while (el && el !== document.body) {
        const cs = getComputedStyle(el);
        if (cs.position === 'fixed') break;
        if (cs.backgroundColor !== 'rgba(0, 0, 0, 0)' && cs.backgroundColor !== 'transparent') card = el;
        el = el.parentElement;
      }
      if (!card || !el || el === document.body) continue;
      const r = card.getBoundingClientRect();
      const cs = getComputedStyle(card);
      const range = document.createRange();
      range.selectNodeContents(card);
      const rects = [...range.getClientRects()];
      cards.push({
        left: r.left, right: r.right, top: r.top, bottom: r.bottom, width: r.width,
        scrollWidth: card.scrollWidth, clientWidth: card.clientWidth,
        bgAlpha: alpha(cs.backgroundColor), opacity: Number(cs.opacity),
        text: card.innerText.replace(/\s+/g, ' '),
        textRight: rects.length ? Math.max(...rects.map((x) => x.right)) : r.right,
      });
    }
    return { innerWidth: window.innerWidth, cards };
  }, L[lang].resultSrc) as Promise<{ innerWidth: number; cards: ToastCard[] }>;
}

/** Карточка целиком в экране, текст не обрезан, фон непрозрачный; на телефоне (<768) — поля 16px слева и справа. */
export function expectCardInside(card: ToastCard, innerWidth: number) {
  expect(card.left, 'тост не выходит за левый край').toBeGreaterThanOrEqual(-0.5);
  expect(card.right, 'тост не выходит за правый край').toBeLessThanOrEqual(innerWidth + 0.5);
  expect(card.textRight, 'текст тоста не уходит за правый край').toBeLessThanOrEqual(innerWidth + 0.5);
  expect(card.scrollWidth, 'текст тоста без горизонтальной обрезки').toBeLessThanOrEqual(card.clientWidth + 1);
  expect(card.bgAlpha * card.opacity, 'фон тоста непрозрачный').toBeGreaterThanOrEqual(0.99);
  if (innerWidth < 768) {
    expect(Math.abs(card.left - 16), `телефон: left = 16 (факт ${card.left})`).toBeLessThanOrEqual(1);
    expect(Math.abs(innerWidth - 16 - card.right), `телефон: right = ширина − 16 (факт ${card.right} при ${innerWidth})`).toBeLessThanOrEqual(1);
  } else {
    expect(innerWidth - card.right, 'десктоп: тост у правого края (справа сверху)').toBeLessThanOrEqual(48);
    expect(card.top, 'десктоп: тост вверху экрана').toBeLessThan(200);
  }
}
